  GroupExplorerByVar() {
      targetGroup := "{groupType}"

      activeHwnd := WinExist("A")
      if !activeHwnd
          return

      winClass := WinGetClass("ahk_id " activeHwnd)
      if (winClass != "CabinetWClass" && winClass != "ExploreWClass")
          return

      for window in ComObject("Shell.Application").Windows {
          if (window.HWND == activeHwnd) {
              try {
                  window.Document.GroupBy := targetGroup
                  window.Refresh()
              }
              return
          }
      }
  }

